     1→import { connectGM } from './websocket';
     2→import { initCanvas } from './canvas';
     3→import { initTokenLayer } from './tokens';
     4→import type { FogStroke } from './canvas';
     5→import * as api from './api';
     6→
     7→// --- URL params ---
     8→const fragment = new URLSearchParams(location.hash.slice(1));
     9→const adventureId = fragment.get('id') ?? '';
    10→const password = fragment.get('password') ?? '';
    11→
    12→if (!adventureId || !password) {
    13→  document.body.innerHTML = '<p style="padding:2rem">Missing adventure ID or password. <a href="/">Return home</a></p>';
    14→  throw new Error('Missing params');
    15→}
    16→
    17→// --- State ---
    18→let brushRadius = 50;
    19→let brushMode: 'reveal' | 'fog' = 'reveal';
    20→let activeImageId: string | null = null;
    21→let imageList: api.ImageRecord[] = [];
    22→
    23→// --- DOM ---
    24→const adventureNameEl = document.getElementById('adventure-name')!;
    25→const inviteLinkEl = document.getElementById('invite-link')!;
    26→const copyInviteBtn = document.getElementById('copy-invite')!;
    27→const brushSizeSlider = document.getElementById('brush-size') as HTMLInputElement;
    28→const brushSizeLabel = document.getElementById('brush-size-label')!;
    29→const modeRevealBtn = document.getElementById('mode-reveal')!;
    30→const modeFogBtn = document.getElementById('mode-fog')!;
    31→const gallery = document.getElementById('gallery')!;
    32→const uploadInput = document.getElementById('upload-input') as HTMLInputElement;
    33→const statusBar = document.getElementById('status-bar')!;
    34→const canvasArea = document.getElementById('canvas-area')!;
    35→
    36→// --- Canvas ---
    37→const canvasCtrl = initCanvas(canvasArea);
    38→
    39→// --- Token layer (non-interactive for GM) ---
    40→const tokenCtrl = initTokenLayer(
    41→  canvasCtrl.getWrapper(),
    42→  () => canvasCtrl.getImageSize(),
    43→  { interactive: false }
    44→);
    45→
    46→// --- WebSocket ---
    47→const ws = connectGM(adventureId, password);
    48→
    49→ws.on('connect', () => { statusBar.textContent = ''; });
    50→ws.on('disconnect', () => { statusBar.textContent = 'Reconnecting\u2026'; });
    51→ws.on('error', (msg) => { console.error('WS error', msg); });
    52→
    53→ws.on('joined', async (msg) => {
    54→  const adv = msg.adventure as { id: string; name: string; activeImageId: string | null };
    55→  adventureNameEl.textContent = adv.name;
    56→
    57→  try {
    58→    const advData = await api.getAdventure(adventureId, password);
    59→    const inviteUrl = `${location.origin}/player#link=${encodeURIComponent(advData.player_link)}`;
    60→    inviteLinkEl.textContent = inviteUrl;
    61→    copyInviteBtn.onclick = () => {
    62→      navigator.clipboard.writeText(inviteUrl).catch(() => {});
    63→    };
    64→  } catch {}
    65→
    66→  activeImageId = adv.activeImageId;
    67→  imageList = await api.listImages(adventureId, password);
    68→  renderGallery();
    69→
    70→  if (activeImageId) {
    71→    const img = imageList.find(i => i.id === activeImageId);
    72→    if (img) {
    73→      await canvasCtrl.loadImage(`/uploads/${img.filename}`);
    74→      if (typeof msg.fogMask === 'string') {
    75→        await canvasCtrl.applyFogMask(msg.fogMask);
    76→      }
    77→    }
    78→  }
    79→
    80→  const tokens = msg.tokens as Array<{ id: string; name: string; color: string; x: number; y: number }>;
    81→  for (const token of tokens) {
    82→    tokenCtrl.addToken(token);
    83→  }
    84→});
    85→
    86→ws.on('fog:stroke', (msg) => {
    87→  if (msg.imageId === activeImageId) {
    88→    canvasCtrl.applyStroke(msg.stroke as FogStroke);
    89→  }
    90→});
    91→
    92→ws.on('fog:stroke:batch', (msg) => {
    93→  if (msg.imageId === activeImageId) {
    94→    for (const stroke of msg.strokes as FogStroke[]) {
    95→      canvasCtrl.applyStroke(stroke);
    96→    }
    97→  }
    98→});
    99→
   100→ws.on('token:added', (msg) => {
   101→  const token = msg.token as { id: string; name: string; color: string; x: number; y: number };
   102→  tokenCtrl.addToken(token);
   103→});
   104→
   105→ws.on('token:moved', (msg) => {
   106→  tokenCtrl.moveToken(msg.tokenId as string, msg.x as number, msg.y as number);
   107→});
   108→
   109→ws.on('token:removed', (msg) => {
   110→  tokenCtrl.removeToken(msg.tokenId as string);
   111→});
   112→
   113→ws.on('map:switched', async (msg) => {
   114→  activeImageId = msg.imageId as string;
   115→  imageList = await api.listImages(adventureId, password);
   116→  const img = imageList.find(i => i.id === activeImageId);
   117→  if (img) {
   118→    await canvasCtrl.loadImage(`/uploads/${img.filename}`);
   119→    if (typeof msg.fogMask === 'string') {
   120→      await canvasCtrl.applyFogMask(msg.fogMask);
   121→    }
   122→  }
   123→  renderGallery();
   124→  tokenCtrl.render();
   125→});
   126→
   127→// --- Gallery ---
   128→function renderGallery() {
   129→  gallery.innerHTML = '';
   130→  for (const img of imageList) {
   131→    const item = document.createElement('div');
   132→    item.className = 'gallery-item' + (img.id === activeImageId ? ' active' : '');
   133→
   134→    const thumb = document.createElement('img');
   135→    thumb.src = `/uploads/${img.filename}`;
   136→    thumb.alt = img.original_name;
   137→    thumb.title = img.original_name;
   138→    item.appendChild(thumb);
   139→
   140→    item.addEventListener('click', () => {
   141→      ws.send({ type: 'map:switch', imageId: img.id });
   142→    });
   143→    gallery.appendChild(item);
   144→  }
   145→}
   146→
   147→// --- Upload ---
   148→uploadInput.addEventListener('change', async () => {
   149→  const file = uploadInput.files?.[0];
   150→  if (!file) return;
   151→  try {
   152→    await api.uploadImage(adventureId, password, file);
   153→    imageList = await api.listImages(adventureId, password);
   154→    renderGallery();
   155→  } catch (e) {
   156→    console.error('Upload failed', e);
   157→  }
   158→  uploadInput.value = '';
   159→});
   160→
   161→// --- Brush controls ---
   162→brushSizeSlider.addEventListener('input', () => {
   163→  brushRadius = parseInt(brushSizeSlider.value, 10);
   164→  brushSizeLabel.textContent = `${brushRadius}px`;
   165→});
   166→
   167→function setMode(mode: 'reveal' | 'fog') {
   168→  brushMode = mode;
   169→  modeRevealBtn.classList.toggle('active', mode === 'reveal');
   170→  modeFogBtn.classList.toggle('active', mode === 'fog');
   171→}
   172→
   173→modeRevealBtn.addEventListener('click', () => setMode('reveal'));
   174→modeFogBtn.addEventListener('click', () => setMode('fog'));
   175→
   176→// --- Brush interaction ---
   177→const eventTarget = canvasCtrl.getEventTarget();
   178→let isDrawing = false;
   179→const pending: FogStroke[] = [];
   180→let lastFlush = 0;
   181→const FLUSH_INTERVAL = 1000 / 60;
   182→
   183→function makeStroke(clientX: number, clientY: number): FogStroke {
   184→  const pos = canvasCtrl.screenToImage(clientX, clientY);
   185→  return { x: pos.x, y: pos.y, radius: brushRadius, mode: brushMode };
   186→}
   187→
   188→function flushPending() {
   189→  if (pending.length === 0) return;
   190→  if (pending.length === 1) {
   191→    ws.send({ type: 'fog:stroke', stroke: pending[0] });
   192→  } else {
   193→    ws.send({ type: 'fog:stroke:batch', strokes: pending.slice() });
   194→  }
   195→  pending.length = 0;
   196→  lastFlush = Date.now();
   197→}
