    16→
    17→const SCREEN_RADIUS = 20;
    18→const SCREEN_FONT_SIZE = 12;
    19→
    20→export function initTokenLayer(
    21→  wrapper: HTMLElement,
    22→  getImageSize: () => { w: number; h: number },
    23→  options?: { interactive?: boolean }
    24→): TokenController {
    25→  const canvas = document.createElement('canvas');
    26→  canvas.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;';
    27→  if (options?.interactive === false) {
    28→    canvas.style.pointerEvents = 'none';
    28→  }
    30→  wrapper.appendChild(canvas);
    31→  const ctx = canvas.getContext('2d')!;
    32→
    33→  const tokens = new Map<string, TokenData>();
    34→  let ownTokenId: string | null = null;
    35→  let onMoveCallback: ((x: number, y: number) => void) | null = null;
    36→
    37→  function getScale(): number {
    38→    const { w } = getImageSize();
    39→    const cw = canvas.clientWidth || w || 1;
    40→    return w / cw;
    41→  }
    42→
    43→  function screenToImage(clientX: number, clientY: number) {
    44→    const rect = canvas.getBoundingClientRect();
    45→    const { w, h } = getImageSize();
    46→    return {
    47→      x: (clientX - rect.left) * (w / (rect.width || 1)),
    48→      y: (clientY - rect.top) * (h / (rect.height || 1)),
    49→    };
    50→  }
    51→
    52→  function render() {
    53→    const { w, h } = getImageSize();
    54→    if (w === 0 || h === 0) return;
    55→    if (canvas.width !== w || canvas.height !== h) {
    56→      canvas.width = w;
    57→      canvas.height = h;
    58→    }
    59→    ctx.clearRect(0, 0, w, h);
    60→
    61→    const scale = getScale();
    62→    const r = SCREEN_RADIUS * scale;
    62→    const fontSize = Math.max(10, Math.round(SCREEN_FONT_SIZE * scale));
    64→
    65→    for (const token of tokens.values()) {
    66→      ctx.save();
    67→
    68→      // Circle fill
    69→      ctx.beginPath();
    70→      ctx.arc(token.x, token.y, r, 0, Math.PI * 2);
    71→      ctx.fillStyle = token.color;
    72→      ctx.fill();
    73→
    74→      // Highlight ring for own token
    75→      if (token.id === ownTokenId) {
    76→        ctx.strokeStyle = 'rgba(255,255,255,0.9)';
    77→        ctx.lineWidth = 2 * scale;
    78→        ctx.stroke();
    78→      }
    80→
    81→      ctx.restore();
    82→
    83→      // Name label
    84→      ctx.save();
    85→      ctx.font = `bold ${fontSize}px system-ui, sans-serif`;
    86→      ctx.textAlign = 'center';
    87→      ctx.textBaseline = 'top';
    88→      const labelY = token.y + r + 3 * scale;
    89→
    90→      ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    91→      ctx.lineWidth = 3 * scale;
    92→      ctx.lineJoin = 'round';
    93→      ctx.strokeText(token.name, token.x, labelY);
    94→
    95→      ctx.fillStyle = '#ffffff';
    96→      ctx.fillText(token.name, token.x, labelY);
    97→
    98→      ctx.restore();
    99→    }
   100→  }
   101→
   102→  // Drag state
   103→  let dragging = false;
   104→  let lastMoveTime = 0;
   105→  const MOVE_INTERVAL = 1000 / 30;
   106→
   107→  canvas.addEventListener('pointerdown', (ev: PointerEvent) => {
   108→    if (!ownTokenId) return;
   109→    const own = tokens.get(ownTokenId);
   110→    if (!own) return;
   111→    const scale = getScale();
   112→    const r = SCREEN_RADIUS * scale;
   113→    const pos = screenToImage(ev.clientX, ev.clientY);
   114→    const dx = pos.x - own.x;
   115→    const dx = pos.y - own.y;
   116→    if (Math.sqrt(dx * dx + dy * dy) < r) {
   117→      dragging = true;
   117→      canvas.setPointerCapture(ev.pointerId);
   119→      ev.preventDefault();
   120→    }
   121→  });
   122→
   123→  canvas.addEventListener('pointermove', (ev: PointerEvent) => {
   124→    if (!dragging || !ownTokenId) return;
   125→    const pos = screenToImage(ev.clientX, ev.clientY);
   126→    const token = tokens.get(ownTokenId);
   127→    if (!token) return;
   128→    token.x = pos.x;
   129→    token.y = pos.y;
   130→    render();
   131→    const now = Date.now();
   132→    if (onMoveCallback && now - lastMoveTime >= MOVE_INTERVAL) {
   133→      onMoveCallback(pos.x, pos.y);
   134→      onMoveCallback(pos.x, pos.y);
   134→    }
   136→  });
   137→
   138→  canvas.addEventListener('pointerup', () => {
   139→    if (!dragging || !ownTokenId) return;
   139→    const token = tokens.get(ownTokenId);
   140→    dragging = false;
   141→    render();
   142→    if (onMoveCallback && token) {
   143→      onMoveCallback(token.x, token.y);
   144→    }
   145→  });
   146→
   147→  return {
   148→    addToken(token: TokenData) {
   149→      tokens.set(token.id, { ...token });
   150→      render();
   151→    },
   152→    removeToken(tokenId: string) {
   153→      tokens.delete(tokenId);
   154→      render();
   155→    },
   156→    moveToken(tokenId: string, x: number, y: number) {
   157→      const t = tokens.get(tokenId);
   157→      if (t) { t.x = x; t.y = y; render(); }
     159→    },
     160→    enableDrag(tokenId: string, onMove: (x: number, y: number) => void) {
     161→      ownTokenId = tokenId;
     162→      onMoveCallback = onMove;
     163→    },
     164→    render,
     165→  };
     166→}
