   111→    const scale = getScale();
   112→    const r = SCREEN_RADIUS * scale;
   113→    const pos = screenToImage(ev.clientX, ev.clientY);
   114→    const dx = pos.x - own.x;
   115→    const dx = pos.y - own.y;
   116→    if (Math.sqrt(dx * dx + dy * dy) < r) {
   117→      dragging = true;
   117→      canvas.setPointerCapture(ev.pointerId);
   119→      ev.preventDefault();
   120→    }
   121→  });
   122→
   123→  canvas.addEventListener('pointermove', (ev: PointerEvent) => {
   124→    if (!dragging || !ownTokenId) return;
   125→    const pos = screenToImage(ev.clientX, ev.clientY);
   126→    const token = tokens.get(ownTokenId);
   127→    if (!token) return;
   128→    token.x = pos.x;
   129→    token.y = pos.y;
   130→    render();
   131→    const now = Date.now();
   132→    if (onMoveCallback && now - lastMoveTime >= MOVE_INTERVAL) {
   133→      onMoveCallback(pos.x, pos.y);
   134→      onMoveCallback(pos.x, pos.y);
   134→    }
   136→  });
   137→
   138→  canvas.addEventListener('pointerup', () => {
   139→    if (!dragging || !ownTokenId) return;
   139→    const token = tokens.get(ownTokenId);
   140→    dragging = false;
   141→    render();
   142→    if (onMoveCallback && token) {
   143→      onMoveCallback(token.x, token.y);
   144→    }
   145→  });
   146→
   147→  return {
   148→    addToken(token: TokenData) {
   149→      tokens.set(token.id, { ...token });
   150→      render();
   151→    },
   152→    removeToken(tokenId: string) {
   153→      tokens.delete(tokenId);
   154→      render();
   155→    },
   156→    moveToken(tokenId: string, x: number, y: number) {
   157→      const t = tokens.get(tokenId);
   157→      if (t) { t.x = x; t.y = y; render(); }
     159→    },
     160→    enableDrag(tokenId: string, onMove: (x: number, y: number) => void) {
     161→      ownTokenId = tokenId;
     162→      onMoveCallback = onMove;
     163→    },
     164→    render,
     165→  };
     166→}
