     1→export interface FogStroke {
     2→  x: number;
     3→  y: number;
     4→  radius: number;
     5→  mode: 'reveal' | 'fog';
     6→}
     7→
     8→export interface CanvasController {
     9→  loadImage(url: string): Promise<void>;
    10→  applyFogMask(base64: string): Promise<void>;
    11→  applyStroke(stroke: FogStroke): void;
    12→  drawBrushPreview(imgX: number, imgY: number, radius: number): void;
    13→  clearBrushPreview(): void;
    14→  screenToImage(clientX: number, clientY: number): { x: number; y: number };
    15→  getEventTarget(): HTMLCanvasElement;
    16→  getWrapper(): HTMLElement;
    17→  getImageSize(): { w: number; h: number };
    18→  clear(): void;
    19→}
    20→
    21→async function decompress(data: Uint8Array): Promise<Uint8Array> {
    22→  // Try zlib (deflate with header) first, then raw deflate
    23→  for (const fmt of ['deflate', 'deflate-raw'] as CompressionFormat[]) {
    24→    try {
    25→      const ds = new DecompressionStream(fmt);
    26→      const writer = ds.writable.getWriter();
    27→      const reader = ds.readable.getReader();
    28→      // Clone data to avoid detached buffer on retry
    29→      writer.write(data.slice());
    30→      writer.close();
    31→      const chunks: Uint8Array[] = [];
    32→      for (;;) {
    33→        const { done, value } = await reader.read();
    34→        if (done) break;
    35→        chunks.push(value);
    36→      }
    37→      const total = chunks.reduce((n, c) => n + c.length, 0);
    38→      const out = new Uint8Array(total);
    39→      let off = 0;
    40→      for (const c of chunks) { out.set(c, off); off += c.length; }
    41→      return out;
    42→    } catch {
    43→      // try next format
    44→    }
    45→  }
    46→  throw new Error('Failed to decompress fog mask');
    47→}
    48→
    49→export function initCanvas(container: HTMLElement, options?: { mode?: 'gm' | 'player' }): CanvasController {
    50→  const fogAlpha = options?.mode === 'player' ? 1.0 : 0.85;
    51→  const fogFill = `rgba(0,0,0,${fogAlpha})`;
    52→  const wrapper = document.createElement('div');
    53→  wrapper.style.cssText = 'position:relative;flex-shrink:0;';
    54→  container.appendChild(wrapper);
    55→
    56→  function makeCanvas(): HTMLCanvasElement {
    57→    const c = document.createElement('canvas');
    58→    c.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;';
    59→    wrapper.appendChild(c);
    60→    return c;
    61→  }
    62→
    63→  const mapCanvas = makeCanvas();
    64→  const fogCanvas = makeCanvas();
    65→  const previewCanvas = makeCanvas();
    66→  previewCanvas.style.pointerEvents = 'none';
    67→
    68→  if (options?.mode === 'player') {
    69→    fogCanvas.style.pointerEvents = 'none';
    70→  }
    71→
    72→  const mapCtx = mapCanvas.getContext('2d')!;
    73→  const fogCtx = fogCanvas.getContext('2d')!;
    74→  const previewCtx = previewCanvas.getContext('2d')!;
    75→
    76→  let imgW = 0;
    77→  let imgH = 0;
    78→
    79→  function sizeAll(w: number, h: number) {
    80→    imgW = w;
    81→    imgH = h;
    82→    for (const c of [mapCanvas, fogCanvas, previewCanvas]) {
    83→      c.width = w;
    84→      c.height = h;
    85→    }
    86→    const cw = container.clientWidth || 800;
    87→    const ch = container.clientHeight || 600;
    88→    const scale = Math.min(cw / w, ch / h);
    89→    wrapper.style.width = `${Math.round(w * scale)}px`;
    90→    wrapper.style.height = `${Math.round(h * scale)}px`;
    91→  }
    92→
    93→  function fillFog() {
    94→    fogCtx.save();
    95→    fogCtx.globalCompositeOperation = 'source-over';
    96→    fogCtx.fillStyle = fogFill;
    97→    fogCtx.fillRect(0, 0, imgW, imgH);
    98→    fogCtx.restore();
    99→  }
   100→
   101→  return {
   102→    async loadImage(url: string) {
   103→      const img = new Image();
   104→      await new Promise<void>((res, rej) => {
   105→        img.onload = () => res();
   106→        img.onerror = () => rej(new Error(`Failed to load image: ${url}`));
   107→        img.src = url;
   108→      });
   109→      sizeAll(img.naturalWidth, img.naturalHeight);
   110→      mapCtx.clearRect(0, 0, imgW, imgH);
   111→      mapCtx.drawImage(img, 0, 0);
   112→      fogCtx.clearRect(0, 0, imgW, imgH);
   113→      fillFog();
   114→      previewCtx.clearRect(0, 0, imgW, imgH);
   115→    },
   116→
   117→    async applyFogMask(base64: string) {
   118→      const bin = atob(base64);
   119→      const bytes = new Uint8Array(bin.length);
   120→      for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
   121→      const view = new DataView(bytes.buffer);
   122→      let w = view.getUint32(0, false);
   123→      let h = view.getUint32(4, false);
   124→      if (w === 0 || h === 0) {
   125→        if (imgW === 0) return; // No image loaded yet
   126→        console.warn('Fog mask has 0x0 dimensions, falling back to loaded image dimensions', imgW, imgH);
   127→        w = imgW;
   128→        h = imgH;
   129→      }
   130→      const pixels = await decompress(bytes.slice(8));
   131→      if (imgW !== w || imgH !== h) sizeAll(w, h);
   132→      const id = fogCtx.createImageData(w, h);
   133→      for (let i = 0; i < pixels.length; i++) {
   134→        const v = pixels[i];
   135→        id.data[i * 4 + 0] = 0;
   136→        id.data[i * 4 + 1] = 0;
   137→        id.data[i * 4 + 2] = 0;
   138→        id.data[i * 4 + 3] = Math.round(v * fogAlpha);
   139→      }
   140→      fogCtx.putImageData(id, 0, 0);
   141→    },
   142→
   143→    applyStroke(stroke: FogStroke) {
   144→      if (imgW === 0) return;
   145→      fogCtx.save();
   146→      fogCtx.beginPath();
   147→      fogCtx.arc(stroke.x, stroke.y, stroke.radius, 0, Math.PI * 2);
   148→      if (stroke.mode === 'reveal') {
   149→        fogCtx.globalCompositeOperation = 'destination-out';
   150→        fogCtx.fillStyle = 'rgba(0,0,0,1)';
   151→      } else {
   152→        fogCtx.globalCompositeOperation = 'source-over';
   153→        fogCtx.fillStyle = fogFill;
   154→      }
   155→      fogCtx.fill();
   156→      fogCtx.restore();
   157→    },
   158→
   159→    drawBrushPreview(imgX: number, imgY: number, radius: number) {
   160→      if (imgW === 0) return;
   161→      previewCtx.clearRect(0, 0, imgW, imgH);
   162→      previewCtx.save();
   163→      previewCtx.strokeStyle = 'rgba(255,255,255,0.7)';
   164→      previewCtx.lineWidth = Math.max(1, 2 * (imgW / (wrapper.clientWidth || imgW)));
   165→      previewCtx.beginPath();
   166→      previewCtx.arc(imgX, imgY, radius, 0, Math.PI * 2);
   167→      previewCtx.stroke();
   168→      previewCtx.restore();
   169→    },
   170→
   171→    clearBrushPreview() {
   172→      if (imgW > 0) previewCtx.clearRect(0, 0, imgW, imgH);
   173→    },
   174→
   175→    screenToImage(clientX: number, clientY: number) {
   176→      const rect = fogCanvas.getBoundingClientRect();
   177→      return {
   178→        x: (clientX - rect.left) * (imgW / (rect.width || 1)),
   179→        y: (clientY - rect.top) * (imgH / (rect.height || 1)),
   180→      };
   181→    },
   182→
