  justify-content: center;
  background: #080810;
  overflow: hidden;
  position: relative;
}

#player-info {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.9rem;
}

.player-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.3);
  flex-shrink: 0;
}

.toast {
  position: fixed;
  bottom: 1rem;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(26,26,46,0.95);
  border: 1px solid #2a2a4a;
  border-radius: 4px;
  padding: 0.4rem 0.8rem;
  font-size: 0.85rem;
  color: #ccc;
  pointer-events: none;
  z-index: 100;
}

